import{z as m,x as u,o as r,c as p,q as o,j as t,D as n,d as s,s as l,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"莫比乌斯反演","description":"","frontmatter":{"title":"莫比乌斯反演","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mobius-inversion.md","filePath":"cs/mobius-inversion.md","lastUpdated":1791063341000}'),E={name:"cs/mobius-inversion.md"};function f(A,a,B,h,g,c){const i=u("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="莫比乌斯反演" tabindex="-1">莫比乌斯反演 <a class="header-anchor" href="#莫比乌斯反演" aria-label="Permalink to &quot;莫比乌斯反演&quot;">​</a></h1><div class="epigraph"><p>若 $g(n)=\\sum_{d\\mid n}f(d)$，则 $f(n)=\\sum_{d\\mid n}\\mu(d)g(n/d)$；除数格上的卷积逆就是 $\\mu$。</p><footer>—— 据 Möbius；Apostol, Introduction to Analytic Number Theory；[欧拉函数与莫比乌斯](/cs/euler-mobius) 整理</footer></div><p>上一课<a href="/cs/generating-functions">生成函数</a>是 \\(n\\) 的加法卷积。数论里常用<strong>除数卷积</strong>。\\(\\varphi\\) 课已给 \\(\\mu\\) 与 \\(\\sum_{d\\mid n}\\mu(d)=[n=1]\\)。缺口是反演公式及其算法用：把「含倍数的计数」变成「恰好」的计数。不重写线性筛填 \\(\\mu\\)。后课期望 DP 换概率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(g=f*\\mathbf{1}\\) 则 \\(f=g*\\mu\\)。典型：\\(g(n)\\) 为 \\(1..n\\) 中满足「\\(d\\mid\\gcd\\)」的对数，\\(f\\) 为 \\(\\gcd=k\\) 的个数。实现：枚举 \\(d\\mid n\\) 或整除分块（\\(\\lfloor n/i\\rfloor\\) 段相同）做前缀 \\(\\sum\\mu\\)、$ \\sum\\varphi$。杜教筛点名：用恒等式在亚线性求积性前缀。</p><p>缺口是反演，不是 \\(\\zeta(s)\\)。</p><h3 id="不是容斥的对立面" tabindex="-1">不是容斥的对立面 <a class="header-anchor" href="#不是容斥的对立面" aria-label="Permalink to &quot;不是容斥的对立面&quot;">​</a></h3><p>容斥是子集格的 \\(\\mu\\)；除数格是另一偏序。同一莫比乌斯函数在 \\(n\\) 的因子格上取值正好是数论 \\(\\mu\\)。点名 poset 即可，不写 Möbius 反演的范畴论。</p><p><span class="marginnote">Apostol 数论教科书。整除分块是算法课标准。后课期望 DP 用线性性，不靠 \\(\\mu\\)。</span></p><p><span class="marginnote">\\(n=100\\) 时 \\(\\lfloor 100/i\\rfloor\\) 的取值只有 19 段（100, 50, 33, 25, 20, 16, …, 1），同一段内商相同。整除分块就是按段跳着求和，把 \\(O(n)\\) 的枚举压到 \\(O(\\sqrt n)\\)，这正是反演公式能算得动的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写清 \\(g\\) 与 \\(f\\) 的卷积关系，再乘 \\(\\mu\\)。需要 \\(1..n\\) 前缀则筛 \\(\\mu\\) 或杜教。单点枚举因子 \\(O(\\sqrt n)\\)。</p>',12)),(r(),t(d,null,{default:n(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22g%20%3D%20f%20*%201%22%5D%20--%3E%20INV%5B%22f%20%3D%20g%20*%20%CE%BC%22%5D%0A%20%20INV%20--%3E%20BLK%5B%22%E6%95%B4%E9%99%A4%E5%88%86%E5%9D%97%20%2F%20%E7%AD%9B%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"注意 \\(*\\) 是除数卷积不是生成函数乘。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"初学者容易把这里的 \\(*\\) 当成多项式乘法——它是 Dirichlet（除数）卷积，定义 \\((f*g)(n)=\\sum_{d\\mid n} f(d)\\,g(n/d)\\)，求和跑过 \\(n\\) 的全部因子，是「按倍数关系混合系数」，不是错位相加。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"\\(\\mathbf{1}*\\mu=\\varepsilon\\) 单位 \\([n=1]\\)，故左乘 \\(\\mu\\) 可逆。与容斥：\\(|A\\cup B|=\\) 先加后减，符号即 \\(\\mu\\)。与 Lucas 无关。与 NTT：Dirichlet 卷积可用分治 FFT（DNTT 一类）点名，本课 \\(O(n\\log n)\\) 筛前缀已够许多题。",-1)),(r(),t(d,null,{default:n(()=>[l(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20WANT%5B%22%E6%83%B3%E6%95%B0%20f%3A%20%E6%81%B0%E5%A5%BD%20gcd%20%3D%20k%2C%20%E9%9A%BE%22%5D%20--%3E%20EASY%5B%22%E6%94%B9%E6%95%B0%E5%A5%BD%E7%AE%97%E7%9A%84%20g%3A%20k%20%E6%95%B4%E9%99%A4%20gcd%22%5D%0A%20%20EASY%20--%3E%20SUM%5B%22g(k)%20%3D%20f(k)%20%2B%20f(2k)%20%2B%20f(3k)%20%2B%20...%22%5D%0A%20%20SUM%20--%3E%20MU%5B%22%E4%B8%A4%E8%BE%B9%E4%B9%98%20%CE%BC%2C%20%E9%87%8D%E5%8F%A0%E9%A1%B9%E9%9D%A0%E7%AC%A6%E5%8F%B7%E6%8A%B5%E6%B6%88%22%5D%0A%20%20MU%20--%3E%20BACK%5B%22%E8%A7%A3%E5%87%BA%20f(k)%20%E5%8D%B3%E6%81%B0%E5%A5%BD%E5%80%BC%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">\\(n=6\\) 时反演公式展开是 \\(f(6)=\\mu(1)g(6)+\\mu(2)g(3)+\\mu(3)g(2)+\\mu(6)g(1)\\)，系数 \\(+1, -1, -1, +1\\) 恰好把重复计入的项两两抵消。\\(\\mu\\) 的符号不是装饰，是抵消机制本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写杜教筛完整证明。不写格上一般 \\(\\mu\\)。后课默认：倍数计数 \\(\\leftrightarrow\\) \\(\\mu\\) 反演。下一课概率与期望 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>除数卷积的逆是 \\(\\mu\\)。</li><li>把「整除条件」的求和换成精确 \\(f\\)。</li><li>与 OGF 卷积不是同一 \\(*\\)。</li><li>出处：Möbius；Apostol；\\(\\mu\\) 见 CLRS 第 31 章。</li></ul>',5))])}const _=m(E,[["render",f]]);export{b as __pageData,_ as default};
